SET standard_conforming_strings = ON;
DROP TABLE IF EXISTS "staging"."unidades_demo" CASCADE;
BEGIN;
CREATE TABLE "staging"."unidades_demo"();
ALTER TABLE "staging"."unidades_demo" ADD COLUMN "fid" SERIAL CONSTRAINT "unidades_demo_pk" PRIMARY KEY;
SELECT AddGeometryColumn('staging','unidades_demo','geom',4674,'MULTIPOLYGON',2);
ALTER TABLE "staging"."unidades_demo" ADD COLUMN "dpto" VARCHAR(2);
ALTER TABLE "staging"."unidades_demo" ADD COLUMN "dpto_desc" VARCHAR(20);
ALTER TABLE "staging"."unidades_demo" ADD COLUMN "distrito" VARCHAR(2);
ALTER TABLE "staging"."unidades_demo" ADD COLUMN "dist_desc_" VARCHAR(40);
ALTER TABLE "staging"."unidades_demo" ADD COLUMN "clave" VARCHAR(4);
SELECT setval(pg_get_serial_sequence('"staging"."unidades_demo"', 'fid'), MAX("fid")) FROM "staging"."unidades_demo";
COMMIT;
DROP TABLE IF EXISTS "staging"."vias_demo" CASCADE;
BEGIN;
CREATE TABLE "staging"."vias_demo"();
ALTER TABLE "staging"."vias_demo" ADD COLUMN "fid" SERIAL CONSTRAINT "vias_demo_pk" PRIMARY KEY;
SELECT AddGeometryColumn('staging','vias_demo','geom',4674,'MULTILINESTRING',2);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "dpto" VARCHAR(2);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "dpto_desc" VARCHAR(30);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "distrito" VARCHAR(2);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "dist_desc" VARCHAR(40);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "area" VARCHAR(1);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "nombre" VARCHAR(50);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "tipo_via" VARCHAR(1);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "destipovia" VARCHAR(30);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "roda_via" VARCHAR(1);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "desrodavia" VARCHAR(30);
ALTER TABLE "staging"."vias_demo" ADD COLUMN "long_metro" INT8;
SELECT setval(pg_get_serial_sequence('"staging"."vias_demo"', 'fid'), MAX("fid")) FROM "staging"."vias_demo";
CREATE INDEX "vias_demo_geom_geom_idx" ON "staging"."vias_demo" USING GIST ("geom");
CREATE INDEX "unidades_demo_geom_geom_idx" ON "staging"."unidades_demo" USING GIST ("geom");
COMMIT;
